package com.franco.desco.application.campaign.service;import com.franco.desco.application.campaign.*;import com.franco.desco.application.campaign.port.in.CampaignUseCase;import com.franco.desco.application.campaign.port.out.CampaignPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.campaign.CampaignModels;
public final class CampaignApplicationService implements CampaignUseCase{private final CampaignPersistencePort p;public CampaignApplicationService(CampaignPersistencePort p){this.p=p;}public AppResult<PageResult<CampaignModels.Summary>>list(CampaignCommands.ListCampaigns c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"CAMPANIAS_LISTADAS","CAMPANIAS_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<CampaignModels.Detail>get(CampaignCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"CAMPANIA_CONSULTADA","CAMPANIA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>create(CampaignCommands.Create c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.create(c,i,m),"CAMPANIA_CREADA","CAMPANIA_NO_CREADA");}public AppResult<Void>update(CampaignCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"CAMPANIA_ACTUALIZADA","CAMPANIA_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>activate(CampaignCommands.Transition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.activate(c,i,m),"CAMPANIA_ACTIVADA","CAMPANIA_NO_ACTIVADA",AppStatus.BAD_REQUEST);}public AppResult<Void>close(CampaignCommands.Transition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.close(c,i,m),"CAMPANIA_CERRADA","CAMPANIA_NO_CERRADA",AppStatus.BAD_REQUEST);}public AppResult<Void>cancel(CampaignCommands.Transition c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.cancel(c,i,m),"CAMPANIA_CANCELADA","CAMPANIA_NO_CANCELADA",AppStatus.BAD_REQUEST);}}
